"""Generate synthetic daily grids; stage only those exact generated bytes in an empty DB."""

import argparse
import json
from datetime import UTC, date, datetime, timedelta
from pathlib import Path

from sqlalchemy import text
from sqlalchemy.exc import SQLAlchemyError

from app.db import create_db_engine
from app.ingest.local import IngestionError, load_directory
from app.ingest.pipeline import import_directory


def files(first: date, generated_at: datetime) -> dict[str, str]:
    days = [first + timedelta(days=i) for i in range(7)]
    manifest = {
        "version": 1,
        "start_date": first.isoformat(),
        "window": {"start": "08:00", "end": "22:00"},
        "snapshots": [
            {"date": day.isoformat(), "fetched_at": generated_at.isoformat()} for day in days
        ],
        "buildings": [
            {
                "source_name": "Synthetic demo building",
                "code": "SYN-DEMO",
                "name": "Synthetic demo building",
                "rooms": [
                    {"source_name": f"SYN-DEMO-{n}", "room_number": str(n), "source_id": 9000 + i}
                    for i, n in enumerate([101, 102], 1)
                ],
            }
        ],
    }
    result = {"manifest.json": json.dumps(manifest, indent=2) + "\n"}
    for day in days:
        rows = []
        for slot in range(28):
            minute = 480 + slot * 30
            cells = []
            for booking in (4, 8):
                if slot == booking:
                    cells.append(
                        '<td class="event rightcell" rowspan="2">Synthetic demo booking</td>'
                    )
                elif slot != booking + 1:
                    cells.append('<td class="lastcell">&nbsp;</td>')
            rows.append(
                f'<tr><td class="time">{minute // 60:02}:{minute % 60:02}</td>{"".join(cells)}</tr>'
            )
        result[f"{day}.html"] = f'''<html><input id="labtime" value="{day}">
<div id="contentwrapper"><table class="tableform"><caption>Synthetic demo building</caption>
<thead><tr><th></th>
<th class="smallth"><a href="?rfilter=9001">SYN-DEMO-101 (20)</a></th>
<th class="smallth"><a href="?rfilter=9002">SYN-DEMO-102 (40)</a></th>
</tr></thead><tbody>{"".join(rows)}</tbody></table></div></html>'''
    return result


def generate(directory: Path, first: date, generated_at: datetime):
    if generated_at.tzinfo is None:
        raise ValueError("Generation time must be timezone-aware")
    content = files(first, generated_at.astimezone(UTC))
    directory.mkdir(parents=True, exist_ok=False)
    for name, value in content.items():
        (directory / name).write_bytes(value.encode("utf-8"))
    return load_directory(directory).report()


def validate_synthetic(directory: Path):
    bundle = load_directory(directory)
    expected = files(bundle.dates[0], bundle.source_fetched_at)
    if any(
        (directory / name).read_bytes() != value.encode("utf-8") for name, value in expected.items()
    ):
        raise IngestionError("not_generated_synthetic")
    return bundle


def stage(engine, directory: Path):
    validate_synthetic(directory)
    with engine.connect() as conn:
        occupied = conn.scalar(
            text("""SELECT
            EXISTS(SELECT 1 FROM utscvacant.buildings) OR
            EXISTS(SELECT 1 FROM utscvacant.rooms) OR
            EXISTS(SELECT 1 FROM utscvacant.datasets) OR
            EXISTS(SELECT 1 FROM utscvacant.ingestion_runs)""")
        )
    if occupied:
        raise IngestionError("staging_requires_empty_schedule")
    return import_directory(engine, directory)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    commands = parser.add_subparsers(dest="command", required=True)
    generate_cmd = commands.add_parser("generate")
    generate_cmd.add_argument("directory", type=Path)
    generate_cmd.add_argument("--start-date", type=date.fromisoformat, required=True)
    stage_cmd = commands.add_parser("stage")
    stage_cmd.add_argument("directory", type=Path)
    stage_cmd.add_argument("--confirm-empty-staging", action="store_true", required=True)
    args = parser.parse_args()
    engine = None
    try:
        if args.command == "generate":
            report = generate(args.directory, args.start_date, datetime.now(UTC))
        else:
            validate_synthetic(args.directory)  # Reject non-generated inputs before connecting.
            engine = create_db_engine("INGESTION_DATABASE_URL")
            report = stage(engine, args.directory)
        print(json.dumps(report, default=str, indent=2))
        return 0
    except IngestionError as error:
        print(json.dumps({"status": "failed", "error_code": error.code}))
        return 2
    except (OSError, ValueError, SQLAlchemyError):
        print(json.dumps({"status": "failed", "error_code": "staging_setup_failed"}))
        return 2
    finally:
        if engine is not None:
            engine.dispose()


if __name__ == "__main__":
    raise SystemExit(main())
